def get_installed_packages(self) -> List[Dict[str, any]]:
    """Get installed Pacman packages with license information."""
    try:
        result = subprocess.run(
            ["pacman", "-Q"],
            capture_output=True,
            text=True,
            check=True
        )

        packages = []
        for line in result.stdout.strip().split('\n'):
            if line.strip():
                parts = line.split()
                if len(parts) >= 2:
                    package_name = parts[0]
                    package_info = {
                        "name": package_name,
                        "display_name": package_name,
                        "version": parts[1],
                        "manager": "pacman",
                        "licenses": self._get_pacman_license(package_name)
                    }
                    packages.append(package_info)
        return packages
    except (subprocess.CalledProcessError, FileNotFoundError):
        return []

def _get_pacman_license(self, package_name: str) -> List[str]:
    """Get license information for a Pacman package."""
    try:
        result = subprocess.run(
            ["pacman", "-Qi", package_name],
            capture_output=True,
            text=True,
            check=True
        )

        # Parse the output to find license information
        for line in result.stdout.split('\n'):
            if line.startswith('Licenses'):
                # Extract licenses after the colon
                license_part = line.split(':', 1)[1].strip()
                if license_part and license_part != 'None':
                    # Split multiple licenses
                    licenses = [lic.strip() for lic in license_part.split()]
                    return licenses if licenses else ["unknown"]

        return ["unknown"]

    except (subprocess.CalledProcessError, FileNotFoundError):
        return ["unknown"]
